mkdir -p /tmp/sms-check && cat > /tmp/sms-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g1-2/bot.mjs';

const GOOD_BODY = 'Flash sale today! Reply STOP to opt out.';
const base = (over = {}) => ({
  kind: 'marketing',
  body: GOOD_BODY,
  to: { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: true, optedOutAt: null, ...over.to },
  ...Object.fromEntries(Object.entries(over).filter(([k]) => k !== 'to')),
});
// Local wall-clock time in Chicago -> UTC Date (Oct 22 2026 is CDT, UTC-5)
const chicago = (h, m = 0) => new Date(Date.UTC(2026, 9, 22, h + 5, m));
const ok = { allowed: true, reason: null };
const no = (reason) => ({ allowed: false, reason });

// Allowed marketing inside the window
assert.deepEqual(checkSms(base(), chicago(12)), ok);
assert.deepEqual(checkSms(base(), chicago(8, 0)), ok, '08:00 start is allowed');
assert.deepEqual(checkSms(base(), chicago(20, 59)), ok, '20:59 is allowed');

// Quiet hours
assert.deepEqual(checkSms(base(), chicago(7, 59)), no('outside_quiet_hours'));
assert.deepEqual(checkSms(base(), chicago(21, 0)), no('outside_quiet_hours'));
assert.deepEqual(checkSms(base(), chicago(0, 30)), no('outside_quiet_hours'));

// Time zone is the customer's, not the server's: same instant, Tokyo is 02:00 next day
const tokyo = base({ to: { phone: '+13125550142', timeZone: 'Asia/Tokyo', marketingConsent: true, optedOutAt: null } });
assert.deepEqual(checkSms(tokyo, chicago(12)), no('outside_quiet_hours'));
const la = base({ to: { phone: '+13125550142', timeZone: 'America/Los_Angeles', marketingConsent: true, optedOutAt: null } });
assert.deepEqual(checkSms(la, chicago(16)), ok, '16:00 Chicago = 14:00 LA');
assert.deepEqual(checkSms(la, chicago(14)), no('outside_quiet_hours'), '14:00 Chicago = 12:00 LA? no: 12:00 LA is allowed');

// Consent
assert.deepEqual(checkSms(base({ to: { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: false, optedOutAt: null } }), chicago(12)), no('no_marketing_consent'));

// Opt-out blocks both kinds; transactional ignores time window and consent
const out = { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: true, optedOutAt: '2026-10-01T10:00:00Z' };
assert.deepEqual(checkSms({ kind: 'marketing', body: GOOD_BODY, to: out }, chicago(12)), no('opted_out'));
assert.deepEqual(checkSms({ kind: 'transactional', body: 'Code 123456', to: out }, chicago(12)), no('opted_out'));
assert.deepEqual(checkSms({ kind: 'marketing', body: GOOD_BODY, to: { ...out, optedOutAt: 'garbage' } }, chicago(12)), no('invalid_opt_out_timestamp'));

// Transactional: allowed at any hour, no consent needed
const tx = { kind: 'transactional', body: 'Your code is 123456', to: { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: false, optedOutAt: null } };
assert.deepEqual(checkSms(tx, chicago(3)), ok);
assert.deepEqual(checkSms(tx, chicago(23)), ok);

// Opt-out instructions
assert.deepEqual(checkSms(base({ body: 'Flash sale today!' }), chicago(12)), no('missing_opt_out_instructions'));
assert.deepEqual(checkSms(base({ body: 'Reply stop to end' }), chicago(12)), ok, 'STOP is case-insensitive');
assert.deepEqual(checkSms(base({ body: 'Stoplight sale' }), chicago(12)), no('missing_opt_out_instructions'), 'whole word only');

// Input validation
assert.deepEqual(checkSms(base({ kind: 'promo' }), chicago(12)), no('invalid_kind'));
assert.deepEqual(checkSms(base({ body: '   ' }), chicago(12)), no('empty_body'));
assert.deepEqual(checkSms(base({ to: { phone: '+44 20 7946 0958', timeZone: 'Europe/London', marketingConsent: true, optedOutAt: null } }), chicago(12)), no('invalid_phone'));
assert.deepEqual(checkSms(base({ to: { phone: '+11255550142', timeZone: 'America/Chicago', marketingConsent: true, optedOutAt: null } }), chicago(12)), no('invalid_phone'), 'area code starting with 1');
assert.deepEqual(checkSms(base({ to: { phone: '+13125550142', timeZone: 'Mars/Olympus', marketingConsent: true, optedOutAt: null } }), chicago(12)), no('invalid_time_zone'));
assert.deepEqual(checkSms(base(), new Date('nope')), no('invalid_now'));
assert.deepEqual(checkSms(base(), '2026-10-22'), no('invalid_now'));
assert.deepEqual(checkSms(null, chicago(12)), no('invalid_message'));

// Server TZ independence: run under different TZ env values
console.log('all assertions passed');
EOF
cd /tmp/sms-check && for tz in UTC Asia/Kolkata America/New_York Pacific/Kiritimati; do echo "TZ=$tz"; TZ=$tz node check.mjs || exit 1; done

