s=s.replace(/assert\.deepEqual\(checkSms\(la, chicago\(14\)\).*\n/, "assert.deepEqual(checkSms(la, chicago(23)), no(\x27outside_quiet_hours\x27), \x2723:00 Chicago = 21:00 LA is blocked\x27);\n");
